import{_ as o,o as t,c as r,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"ADR-015: Local server security for AI endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"adr/015-local-server-security.md","filePath":"adr/015-local-server-security.md"}'),a={name:"adr/015-local-server-security.md"};function s(i,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-015-local-server-security-for-ai-endpoints" tabindex="-1">ADR-015: Local server security for AI endpoints <a class="header-anchor" href="#adr-015-local-server-security-for-ai-endpoints" aria-label="Permalink to &quot;ADR-015: Local server security for AI endpoints&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-11-01</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR-012 kept the dashboard on 127.0.0.1 with same-origin checks. ADR-014 adds endpoints meant for programs (<code>/mcp</code>, <code>/api/v1</code>) that can write episodes and start renders. Any web page the person visits can send requests to localhost, and DNS rebinding can make such a page look same-origin to a naive server. Some people also want to reach the dashboard from another machine (a container, WSL, a second computer on their network).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ul><li><strong>Bind address.</strong> <code>reelforge studio</code> binds to 127.0.0.1. <code>--host &lt;address&gt;</code> (or <code>REELFORGE_HOST</code>) binds elsewhere; nothing else changes the default. The per-episode editor servers stay on 127.0.0.1.</li><li><strong>Host and Origin allow-list (DNS rebinding).</strong> Every request and WebSocket must carry a Host header that is a loopback name (<code>127.0.0.0/8</code>, <code>localhost</code>, <code>[::1]</code>) on the server&#39;s port, the bind address itself when it is a specific address, or a name listed in <code>REELFORGE_ALLOWED_HOSTS</code> (comma separated, optionally with a port). An Origin header, when present, must name an allowed host the same way. Anything else gets 403.</li><li><strong>No CORS.</strong> No <code>Access-Control-Allow-Origin</code> header is ever sent, so other origins cannot read responses. Writes are JSON-only (<code>content-type: application/json</code>), which HTML forms cannot send.</li><li><strong>Bearer token.</strong> A token is created on first use: 32 random bytes, base64url, stored in the user config folder (<code>%APPDATA%\\reelforge\\token</code> on Windows, <code>~/Library/Application Support/reelforge/token</code> on macOS, <code>$XDG_CONFIG_HOME/reelforge/token</code> or <code>~/.config/reelforge/token</code> on Linux; overridable with <code>REELFORGE_CONFIG_DIR</code>), with mode 0600 in a 0700 folder where the platform supports it. It is required as <code>Authorization: Bearer &lt;token&gt;</code> on <code>/mcp</code> and <code>/api/v1</code> when the bind address is not loopback or <code>REELFORGE_REQUIRE_TOKEN=1</code>. Comparison is constant-time.</li><li><strong>Remote peers.</strong> When bound to another address, a client on another computer may reach only <code>/mcp</code>, <code>/api/v1</code>, <code>/llms.txt</code>, <code>/llms-full.txt</code> and <code>/.well-known/mcp.json</code>. The dashboard UI, its internal API and its WebSocket answer only to the same computer, because a Host header is trivial to forge outside a browser and those endpoints carry no token.</li><li><strong>Token display.</strong> The Connect AI page gets the token from <code>/api/connect</code> only when the request comes from this computer and the browser marks it same-origin (<code>Sec-Fetch-Site</code>).</li><li>Path sandboxing (every path resolved inside the project root, outputs served only from <code>out/</code>) and upload limits (1 GB, audio types only) stay as in ADR-012.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The default stays local and needs no token, so existing setups keep working. Exposing the dashboard is explicit, needs the token for every AI endpoint and still keeps the human UI on the local machine. Plain HTTP carries the token in clear text: on an untrusted network, put the dashboard behind a TLS proxy and list its host name in <code>REELFORGE_ALLOWED_HOSTS</code>.</p>',8)])])}const m=o(a,[["render",s]]);export{u as __pageData,m as default};
